<template>
  <div id="routine-text">
    <button id="back" @click="back">→ חזרה</button>

    <div class="page-title">{{ title }}</div>
    <div class="divider"></div>

    <div class="matzav-panel">
      <div class="matzav-sections">
        <div v-for="(section, si) in sections" :key="si" class="matzav-section">
          <button class="section-toggle" @click="toggleSection(si)">
            <span class="section-title">{{ section.title }}</span>
            <span class="toggle-icon">{{ openSections[si] ? '−' : '+' }}</span>
          </button>
          <div v-if="openSections[si]" class="section-body">
            <ul v-if="section.type === 'list'" class="bullet-list">
              <li v-for="(item, ii) in section.items" :key="ii" class="bullet-item">{{ item }}</li>
            </ul>

            <div v-else-if="section.type === 'table'" class="table-wrapper">
              <table class="matzav-table">
                <thead>
                  <tr>
                    <th v-for="(head, hi) in section.headers" :key="hi">{{ head }}</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(row, ri) in section.rows" :key="ri">
                    <td v-for="(cell, ci) in row" :key="ci">{{ cell }}</td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div v-else-if="section.type === 'merged-schedule'" class="table-wrapper">
              <div class="legend">
                <div v-for="(leg, li) in section.legend" :key="li" class="legend-item">
                  <span class="legend-swatch" :style="{ background: leg.color }"></span>
                  <span class="legend-label">{{ leg.label }}</span>
                </div>
              </div>
              <table class="matzav-table">
                <thead>
                  <tr>
                    <th v-for="(head, hi) in section.headers" :key="hi">{{ head }}</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(row, ri) in section.rows" :key="ri">
                    <td v-for="(cell, ci) in row.cells" :key="ci" :style="row.color ? { background: row.color } : {}">
                      <span v-if="ci === 0 && row.dayLabel" class="day-badge">{{ row.dayLabel }}</span>
                      {{ cell }}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div v-else-if="section.type === 'schedule'" class="schedule-groups">
              <div v-for="(group, gi) in section.groups" :key="gi" class="schedule-group">
                <div class="schedule-label">{{ group.label }}</div>
                <div class="schedule-times">
                  <span v-for="(time, ti) in group.times" :key="ti" class="time-chip">{{ time }}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import json from "../../text.json";
export default {
  name: "routine-text",
  data() {
    const sections = json.routineText.sections;
    const openSections = {};
    sections.forEach((_, i) => { openSections[i] = false; });
    return {
      title: json.routineText.title,
      sections,
      openSections
    };
  },
  mounted() {
    const tp = document.getElementById('text-page');
    if (tp) tp.scrollTop = 0;
    window.scrollTo(0, 0);
  },
  methods: {
    back() {
      this.$emit("back");
    },
    toggleSection(i) {
      this.$set(this.openSections, i, !this.openSections[i]);
    }
  }
};
</script>

