<template>
    <div id="fire-map-wrapper" :class="{ fullscreen: isFullscreen }">
        <div id="fire-map-container" ref="mapContainer"></div>
        <button v-if="!isMobile" id="expand-btn" @click="toggleFullscreen">
            {{ isFullscreen ? '✕' : '⛶' }}
        </button>

        <div v-if="num === 'shooting-range' || toggleableLayers.length" id="legend-wrapper" @click.stop>
            <div class="legend-panel" dir="rtl">
                <div v-if="num === 'shooting-range'" class="legend-item legend-item--locked">
                    <span class="legend-check locked">✓</span>
                    <span class="legend-swatch" style="background:#3a6b4a"></span>
                    <span>מטווחים</span>
                </div>
                <div v-for="layer in toggleableLayers" :key="layer.key"
                     class="legend-item" @click="toggleLayer(layer.key)">
                    <span class="legend-check" :class="{ checked: activeLayers[layer.key] }">
                        {{ activeLayers[layer.key] ? '✓' : '' }}
                    </span>
                    <span class="legend-swatch" :style="{ background: layer.color }"></span>
                    <span>{{ layer.label }}</span>
                </div>
            </div>
        </div>

        <transition :name="isMobile ? 'panel-up' : 'panel-right'">
            <div v-if="panelOpen && activePoi" class="poi-panel" @click.stop
                 :class="'poi-panel--' + panelState"
                 :style="panelDragStyle">
                <div v-if="isMobile" class="poi-panel-handle"
                     @touchstart="onHandleTouchStart"
                     @touchmove.prevent="onHandleTouchMove"
                     @touchend="onHandleTouchEnd"></div>
                <button class="poi-panel-close" @click="closePanel">✕</button>
                <div class="poi-panel-content" dir="rtl">
                    <div v-if="activePoi.name" class="poi-panel-title">{{ activePoi.name }}</div>
                    <template v-if="isMobile && activePoi.txt && activePoi.txt.length">
                        <p v-for="(t, i) in activePoi.txt" :key="i" class="poi-panel-line">• {{ t }}</p>
                    </template>
                    <ul v-else-if="!isMobile && activePoi.txt && activePoi.txt.length" class="poi-panel-list">
                        <li v-for="(t, i) in activePoi.txt" :key="i" class="poi-panel-line">{{ t }}</li>
                    </ul>
                </div>
            </div>
        </transition>
    </div>
</template>

<script>
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import json from "../../text.json";
import pinUrl from "../assets/media/pin.svg";
import shaftUrl from "../assets/media/shaft.svg";

const AREA_NAMES = {
    "104":         "ש.א 104",
    "108":         "ש.א 108",
    "111":         "ש.א 111",
    "112":         "ש.א 112",
    "108_sumka":   "108 סומקה",
    "108_north":   "108 צפון",
    "108_center":  "108 מרכז",
    "108_south":   "108 דרום",
    "baf-elyakim": 'בא"פ אליקים',
    "112_east":  "112 מזרח",
    "112_north": "112 צפון",
    "112_west":  "112 מערב",
    "112_south": "112 דרום",
    "111_lower":        "111 תחתון",
    "111_upper":        "111 עליון",
    "111_west_bananas": "מערב בננות",
    "111_south":        "111 דרום",
    "111_west_center":   "מרכז",
    "111_main_center":   "111 מרכז",
    "111_north":        "111 צפון",
    "104_matzav_hadash":   "מוצב חדש",
    "104_yardena":         "ירדנה",
    "104_carmela":         "כרמלה",
    "104_horoshet_negus":  "חורשת נגוס",
    "104_horoshet_katina": "חורשת קטינה",
    "104_yael_north":      "יעל צפון",
    "104_yael":            "יעל",
    "104_mishkakim_baesh": "משחקים באש",
    "חניה_1": "חניה 1",
    "חניה_2": "חניה 2",
    "חניה_3": "חניה 3",
    "חניה_4": "חניה 4",
    "חניה_5": "חניה 5",
};

// Subzones of 111 that should behave like top-level areas (only when area 111 is active)
const TOPLEVEL_SUBZONES = new Set([
    "111_west_bananas",
    "111_lower",
    "111_upper"
]);

// Manual label position overrides — used instead of centroid when specified
const LABEL_POSITIONS = {
    "111_north":        [32.69088, 34.97201],
    "111_west_bananas": [32.6884,  34.97081],
    "111_west_center":  [32.68644, 34.97066],
    "111_south":        [32.68151, 34.97088],
};

function getCentroid(coords) {
    const lat = coords.reduce((s, c) => s + c[0], 0) / coords.length;
    const lng = coords.reduce((s, c) => s + c[1], 0) / coords.length;
    return [lat, lng];
}

function getBBoxArea(coords) {
    const lats = coords.map(c => c[0]);
    const lngs = coords.map(c => c[1]);
    return (Math.max(...lats) - Math.min(...lats)) * (Math.max(...lngs) - Math.min(...lngs));
}

function areaToMinZoom(bboxArea) {
    if (bboxArea > 0.02)  return 11;
    if (bboxArea > 0.005) return 12;
    if (bboxArea > 0.001) return 13;
    return 14;
}

export default {
    name: "fire-map",
    props: ["num"],
    data() {
        return {
            map: null,
            isFullscreen: false,
            isMobile: window.matchMedia("(max-device-width: 600px)").matches,
            labelMarkers: [],
            activePoi: null,
            panelState: "closed",
            activeMarker: null,
            activePolygon: null,
            dragStartY: 0,
            dragDeltaY: 0,
            isDragging: false,
            activeLayers: { shafts: false, tzirim: true, matvaim: false },
            layerGroups: { shafts: null, tzirim: null, matvaim: null },
        };
    },
    computed: {
        panelOpen() {
            return this.panelState !== "closed";
        },
        toggleableLayers() {
            const n = String(this.num);
            const k = (layer) => n === "shooting-range" ? `shooting-range-${layer}` : `${layer}_${n}`;
            const hasTzirim = n === "104" || n === "shooting-range";
            const layers = [];
            if (hasTzirim) layers.push({ key: "tzirim",   label: 'רק"ם',    color: "#7C3AED", jsonKey: k("tzirim")   });
            if (n === "104") layers.push({ key: "matvaim", label: "מטווחים", color: "#3a6b4a", jsonKey: "" });
            return layers;
        },
        panelDragStyle() {
            if (!this.isMobile) return {};
            if (!this.isDragging || this.dragDeltaY === 0) return {};
            return {
                transform: "translateY(" + this.dragDeltaY + "px)",
                transition: "none",
            };
        },
    },
    mounted() {
        this.$nextTick(() => { this._initMap(); });
        document.addEventListener("keydown", this._onEsc);
    },
    beforeDestroy() {
        if (this.map) { this.map.remove(); this.map = null; }
        document.removeEventListener("keydown", this._onEsc);
    },
    methods: {
        _initMap() {
            this.map = L.map(this.$refs.mapContainer, {
                scrollWheelZoom: true,
                zoomControl: false,
                attributionControl: false,
            });
            this.map.invalidateSize();

            L.tileLayer(
                "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
                {
                    attribution: "Tiles &copy; Esri &mdash; Source: Esri, Maxar, Earthstar Geographics",
                    maxZoom: 19,
                }
            ).addTo(this.map);

            if (this.num === "shooting-range") {
                this._initShootingRangeMap();
                return;
            }

            const borders = json["fire-map-borders"];
            const key = String(this.num);
            const subzonePrefix = key + "_";

            Object.entries(borders).forEach(([borderKey, coords]) => {
                if (!coords || !coords.length) return;

                const isActive  = borderKey === key;
                const isSubzone = borderKey.startsWith(subzonePrefix) &&
                                  !(key === "111" && TOPLEVEL_SUBZONES.has(borderKey));

                const w = this.isMobile ? 2 : 1;
                if (isActive) {
                    L.polygon(coords, {
                        color: "#1a1a1a", weight: 2.5 + w,
                        fillColor: "#ffffff", fillOpacity: 0.55,
                    }).addTo(this.map);
                } else if (isSubzone) {
                    L.polygon(coords, {
                        color: "#1a1a1a", weight: 1.5 + w,
                        fillColor: "#000000", fillOpacity: 0.2,
                        dashArray: "5, 5",
                    }).addTo(this.map);
                } else {
                    L.polygon(coords, {
                        color: "#1a1a1a", weight: 2 + w, fillOpacity: 0,
                    }).addTo(this.map);
                }

                const name = AREA_NAMES[borderKey];
                if (name) {
                    const centroid = LABEL_POSITIONS[borderKey] || getCentroid(coords);
                    const minZoom  = areaToMinZoom(getBBoxArea(coords));
                    const marker   = L.marker(centroid, {
                        icon: L.divIcon({
                            className: "",
                            html: `<div class="area-label ${isSubzone ? "area-label--sub" : ""}">${name}</div>`,
                            iconSize: [0, 0],
                            iconAnchor: [0, 0],
                        }),
                        interactive: false,
                        zIndexOffset: isSubzone ? 500 : 1000,
                    });
                    const isMainArea = ["104","108","111","112"].indexOf(borderKey) !== -1;
                    this.labelMarkers.push({ marker, minZoom, isMainArea });
                }
            });

            const mainBorder = borders[key];
            if (mainBorder && mainBorder.length) {
                this.map.fitBounds(L.latLngBounds(mainBorder), { padding: [30, 30] });
            }
            this._initialZoom = this.map.getZoom();
            const mainMinZoom = mainBorder && mainBorder.length
                ? areaToMinZoom(getBBoxArea(mainBorder))
                : 12;

            const pinSize = this.isMobile ? 96 : 40;
            const pinAnchorY = Math.round(pinSize * 0.854);
            const pinIcon = L.icon({
                iconUrl: pinUrl,
                iconSize: [pinSize, pinSize],
                iconAnchor: [pinSize / 2, pinAnchorY],
            });

            this._updateLabels();
            this.map.on("zoomend", this._updateLabels);

            const self = this;
            const shaftCoordSet = new Set(
                (json["shafts-and-routes"] || [])
                    .filter(s => s.isShaft && s.coordinates)
                    .map(s => s.coordinates[0] + "," + s.coordinates[1])
            );
            const pois = json[`poi_${key}`] || [];
            pois.forEach(function(poi) {
                if (!poi.coordinates) return;
                if (shaftCoordSet.has(poi.coordinates[0] + "," + poi.coordinates[1])) return;
                const marker = L.marker(poi.coordinates, { icon: pinIcon }).addTo(self.map);
                if (!poi.txt || !poi.txt.length) return;
                marker.on("click", function(e) {
                    L.DomEvent.stopPropagation(e);
                    self.openPanel(poi, marker);
                });
            });

            this.map.on("click", function() { self.closePanel(); });
            this._buildLayerGroups();
        },

        _initShootingRangeMap() {
            const w = this.isMobile ? 2 : 1;

            // Draw selected fire-map-borders as context outlines
            const SHOOTING_RANGE_BORDERS = new Set(["104", "108", "111", "112", "baf-elyakim"]);
            const borders = json["fire-map-borders"];
            Object.entries(borders).forEach(([borderKey, coords]) => {
                if (!SHOOTING_RANGE_BORDERS.has(borderKey)) return;
                if (!coords || !coords.length) return;
                L.polygon(coords, {
                    color: "#1a1a1a", weight: 2 + w, fillOpacity: 0,
                }).addTo(this.map);
                const name = AREA_NAMES[borderKey];
                if (name) {
                    const centroid = LABEL_POSITIONS[borderKey] || getCentroid(coords);
                    const minZoom  = areaToMinZoom(getBBoxArea(coords));
                    const isMainArea = ["104","108","111","112"].indexOf(borderKey) !== -1;
                    const marker = L.marker(centroid, {
                        icon: L.divIcon({
                            className: "",
                            html: `<div class="area-label">${name}</div>`,
                            iconSize: [0, 0],
                            iconAnchor: [0, 0],
                        }),
                        interactive: false,
                        zIndexOffset: 1000,
                    });
                    this.labelMarkers.push({ marker, minZoom, isMainArea });
                }
            });

            // Draw shooting range polygons on top with click-to-highlight
            const ranges = json["shooting-range-borders"] || [];
            const allCoords = [];
            const self = this;

            ranges.forEach(range => {
                const coords = range.border.map(p => [p.lat, p.lng]);
                allCoords.push(...coords);

                const polygon = L.polygon(coords, {
                    color: "#1a1a1a", weight: 2 + w,
                    fillColor: "#3a6b4a", fillOpacity: 0.55,
                }).addTo(this.map);

                polygon.on("click", function(e) {
                    L.DomEvent.stopPropagation(e);
                    self._setPolygonHighlight(self.activePolygon, false);
                    self.activePolygon = polygon;
                    self._setPolygonHighlight(polygon, true);
                    self.activePoi = { name: range.name, txt: range.txt || [] };
                    self.panelState = "open";
                    self.dragDeltaY = 0;
                    self.isDragging = false;
                });
            });

            if (allCoords.length) {
                this.map.fitBounds(L.latLngBounds(allCoords), { padding: [30, 30] });
            }
            this._initialZoom = this.map.getZoom();
            this._updateLabels();
            this.map.on("zoomend", this._updateLabels);
            this.map.on("click", () => { this.closePanel(); });
            this._buildLayerGroups();
        },

        _buildLayerGroups() {
            const pinSize = this.isMobile ? 96 : 40;
            const pinIcon = L.icon({
                iconUrl: pinUrl,
                iconSize: [pinSize, pinSize],
                iconAnchor: [pinSize / 2, Math.round(pinSize * 0.854)],
            });
            const shaftSize = this.isMobile ? 56 : 24;
            const shaftIcon = L.icon({
                iconUrl: shaftUrl,
                iconSize: [shaftSize, shaftSize],
                iconAnchor: [shaftSize / 2, shaftSize / 2],
            });
            const shaftsAndRoutes = json["shafts-and-routes"] || [];

            this.toggleableLayers.forEach(def => {
                const group = L.layerGroup();

                // Items from per-area JSON array
                (json[def.jsonKey] || []).forEach(item => {
                    if (item.path && item.path.length) {
                        const line = L.polyline(item.path, {
                            color: def.color,
                            weight: this.isMobile ? 4 : 2.5,
                            opacity: 0.85,
                        });
                        if (item.name || (item.txt && item.txt.length)) {
                            line.on("click", e => {
                                L.DomEvent.stopPropagation(e);
                                this.openPanel(item, null);
                            });
                        }
                        group.addLayer(line);
                    } else if (item.coordinates) {
                        const icon = def.key === "shafts" ? shaftIcon : pinIcon;
                        const marker = L.marker(item.coordinates, { icon });
                        marker.on("click", e => {
                            L.DomEvent.stopPropagation(e);
                            this.openPanel(item, marker);
                        });
                        group.addLayer(marker);
                    }
                });

                // Shooting range borders → matvaim layer (polygons)
                if (def.key === "matvaim") {
                    const w = this.isMobile ? 2 : 1;
                    (json["shooting-range-borders"] || []).forEach(range => {
                        const coords = range.border.map(p => [p.lat, p.lng]);
                        const polygon = L.polygon(coords, {
                            color: "#1a1a1a", weight: 2 + w,
                            fillColor: def.color, fillOpacity: 0.55,
                        });
                        polygon.on("click", e => {
                            L.DomEvent.stopPropagation(e);
                            this.openPanel({ name: range.name, txt: range.txt || [] }, null);
                        });
                        group.addLayer(polygon);
                    });
                }

                // Shafts from shafts-and-routes → shafts layer (shaft icon)
                if (def.key === "shafts") {
                    shaftsAndRoutes.forEach(item => {
                        if (!item.isShaft || !item.coordinates) return;
                        const marker = L.marker(item.coordinates, { icon: shaftIcon });
                        marker.on("click", e => {
                            L.DomEvent.stopPropagation(e);
                            this.openPanel(item, marker);
                        });
                        group.addLayer(marker);
                    });
                }

                // Routes from shafts-and-routes → tzirim layer
                if (def.key === "tzirim") {
                    shaftsAndRoutes.forEach(item => {
                        if (!item.isRoute || !item.coordinates || !item.coordinates.length) return;
                        const line = L.polyline(item.coordinates, {
                            color: def.color,
                            weight: this.isMobile ? 4 : 2.5,
                            opacity: 0.85,
                        });
                        if (item.name) {
                            line.on("click", e => {
                                L.DomEvent.stopPropagation(e);
                                this.openPanel(item, null);
                            });
                        }
                        group.addLayer(line);
                    });
                }

                this.layerGroups[def.key] = group;
                if (this.activeLayers[def.key]) group.addTo(this.map);
            });
        },

        toggleLayer(key) {
            this.activeLayers[key] = !this.activeLayers[key];
            const group = this.layerGroups[key];
            if (!group) return;
            if (this.activeLayers[key]) {
                group.addTo(this.map);
            } else {
                group.remove();
            }
        },


        _updateLabels() {
            const zoom = this.map.getZoom();
            this.labelMarkers.forEach(function(item) {
                var threshold;
                if (this.isMobile) {
                    threshold = item.isMainArea ? this._initialZoom : this._initialZoom + 1.5;
                } else {
                    threshold = item.minZoom;
                }
                if (zoom >= threshold) {
                    if (!this.map.hasLayer(item.marker)) item.marker.addTo(this.map);
                } else {
                    if (this.map.hasLayer(item.marker)) item.marker.remove();
                }
            }, this);
        },

        onHandleTouchStart(e) {
            this.dragStartY = e.touches[0].clientY;
            this.dragDeltaY = 0;
            this._rawDragDelta = 0;
            this.isDragging = true;
        },
        onHandleTouchMove(e) {
            if (!this.isDragging) return;
            const delta = e.touches[0].clientY - this.dragStartY;
            this._rawDragDelta = delta;
            // Only apply downward translateY when open; no visual drag when collapsed
            this.dragDeltaY = this.panelState === "open" ? Math.max(0, delta) : 0;
        },
        onHandleTouchEnd() {
            this.isDragging = false;
            const raw = this._rawDragDelta || 0;
            this._rawDragDelta = 0;
            if (this.panelState === "open" && raw > 80) {
                this.panelState = "collapsed";
            } else if (this.panelState === "collapsed" && raw < -60) {
                this.panelState = "open";
            }
            this.dragDeltaY = 0;
        },

        _setPolygonHighlight(polygon, active) {
            if (!polygon) return;
            if (active) {
                polygon.setStyle({ fillColor: "#f5c518", fillOpacity: 0.75 });
            } else {
                polygon.setStyle({ fillColor: "#3a6b4a", fillOpacity: 0.55 });
            }
        },

        _setMarkerHighlight(marker, active) {
            if (!marker) return;
            var el = marker.getElement();
            if (!el) return;
            var img = el.querySelector("img");
            var target = img || el;
            if (active) {
                target.style.filter = "drop-shadow(0 0 3px #fff) drop-shadow(0 0 6px #fff) drop-shadow(0 0 10px #fff) drop-shadow(0 0 14px #fff)";
                target.style.transition = "filter 0.2s ease";
            } else {
                target.style.filter = "";
            }
        },
        openPanel(poi, marker) {
            this._setMarkerHighlight(this.activeMarker, false);
            this.activeMarker = marker || null;
            this._setMarkerHighlight(this.activeMarker, true);
            this.activePoi = poi;
            this.panelState = "open";
            this.dragDeltaY = 0;
            this.isDragging = false;
        },
        closePanel() {
            this._setMarkerHighlight(this.activeMarker, false);
            this.activeMarker = null;
            this._setPolygonHighlight(this.activePolygon, false);
            this.activePolygon = null;
            this.panelState = "closed";
            this.dragDeltaY = 0;
            this.isDragging = false;
        },
        _onEsc(e) {
            if (e.key === "Escape") this.closePanel();
        },

        toggleFullscreen() {
            this.isFullscreen = !this.isFullscreen;
            this.$nextTick(() => { this.map.invalidateSize(); });
        },
    },
};
</script>

