<template>
  <div id="security-text">
    <button id="back" @click="back">→ חזרה</button>

    <div class="page-title">{{ title }}</div>
    <div class="divider"></div>

    <div class="matzav-panel">
      <div class="matzav-sections">
        <div v-for="(section, si) in sections" :key="si" class="matzav-section">
          <button class="section-toggle" @click="toggleSection(si)">
            <span class="section-title">{{ section.title }}</span>
            <span class="toggle-icon">{{ openSections[si] ? '−' : '+' }}</span>
          </button>
          <div v-if="openSections[si]" class="section-body">

            <!-- Plain bullet list -->
            <ul v-if="section.type === 'list'" class="bullet-list">
              <li v-for="(item, ii) in section.items" :key="ii" class="bullet-item">{{ item }}</li>
            </ul>

            <!-- Mixed: plain bullets + sub-headers with numbered children -->
            <div v-else-if="section.type === 'mixed'" class="mixed-list">
              <template v-for="(item, ii) in section.items">
                <div v-if="item.sub" :key="'sub-' + ii" class="sub-block">
                  <div class="sub-header">{{ item.text }}</div>
                  <ol class="sub-list">
                    <li v-for="(child, ci) in item.children" :key="ci" class="sub-item">{{ child }}</li>
                  </ol>
                </div>
                <div v-else :key="'item-' + ii" class="bullet-item-wrap">
                  <span class="bullet-dot"></span>
                  <span>{{ item.text }}</span>
                </div>
              </template>
            </div>

            <!-- Table with legend + optional notes sub-block -->
            <div v-else-if="section.type === 'table-with-notes'" class="table-wrapper">
              <div v-if="section.legend" class="legend">
                <div v-for="(leg, li) in section.legend" :key="li" class="legend-item">
                  <span class="legend-swatch" :style="{ background: leg.color }"></span>
                  <span class="legend-label">{{ leg.label }}</span>
                </div>
              </div>
              <table class="matzav-table">
                <thead>
                  <tr>
                    <th v-for="(head, hi) in section.headers" :key="hi">{{ head }}</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(row, ri) in section.rows" :key="ri">
                    <td
                      v-for="(cell, ci) in row.cells"
                      :key="ci"
                      :style="row.colors && row.colors[ci] ? { background: row.colors[ci] } : {}"
                    >{{ cell }}</td>
                  </tr>
                </tbody>
              </table>
              <div v-if="section.notes" class="sub-block">
                <div class="sub-header">{{ section.notes.text }}</div>
                <ol class="sub-list">
                  <li v-for="(child, ci) in section.notes.children" :key="ci" class="sub-item">{{ child }}</li>
                </ol>
              </div>
            </div>

          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import json from "../../text.json";
export default {
  name: "security-text",
  data() {
    const sections = json.security.sections;
    const openSections = {};
    sections.forEach((_, i) => { openSections[i] = false; });
    return {
      title: json.security.title,
      sections,
      openSections
    };
  },
  mounted() {
    const tp = document.getElementById('text-page');
    if (tp) tp.scrollTop = 0;
    window.scrollTo(0, 0);
  },
  methods: {
    back() {
      this.$emit("back");
    },
    toggleSection(i) {
      this.$set(this.openSections, i, !this.openSections[i]);
    }
  }
};
</script>

<style scoped>
#security-text {
  position: relative;
  width: 100vw;
  min-height: 100vh;
  background: #f5f5f7;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  overflow-y: auto;
  overflow-x: hidden;
  box-sizing: border-box;
  padding: 10vh 4vw 6vh;
}

#back {
  position: fixed;
  right: 1.5vw;
  top: 2.5vh;
  z-index: 7;
  font-family: "assistant-bold";
  font-size: 1vw;
  color: #3a6b4a;
  background: transparent;
  border: 1.5px solid #3a6b4a;
  border-radius: 980px;
  padding: 0.7vh 1.5vw;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
#back:hover {
  background: #3a6b4a;
  color: #ffffff;
}

.page-title {
  font-family: "assistant-extrabold";
  font-size: 2vw;
  color: #1d1d1f;
  margin-bottom: 0;
  letter-spacing: -0.02em;
  direction: rtl;
}

.divider {
  width: 3vw;
  height: 2px;
  background: #d2d2d7;
  border-radius: 2px;
  margin-top: 1vh;
  margin-bottom: 2vh;
}

.matzav-panel {
  width: 52vw;
  background: #ffffff;
  border: 1px solid #e0e0e0;
  border-radius: 12px;
  padding: 2vh 3vw;
  direction: rtl;
  text-align: right;
  margin-bottom: 4vh;
}

.matzav-sections {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.matzav-section {
  border-bottom: 1px solid #e8e8e8;
}
.matzav-section:last-child {
  border-bottom: none;
}

.section-toggle {
  width: 100%;
  background: transparent;
  border: none;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 1.4vh 0;
  cursor: pointer;
  direction: rtl;
  text-align: right;
}
.section-toggle:hover .section-title {
  color: #3a6b4a;
}

.section-title {
  font-family: "assistant-bold";
  font-size: 1.1vw;
  color: #1d1d1f;
  transition: color 0.18s;
}

.toggle-icon {
  font-family: "assistant-bold";
  font-size: 1.4vw;
  color: #3a6b4a;
  line-height: 1;
  margin-left: 0.5vw;
  user-select: none;
}

.section-body {
  display: flex;
  flex-direction: column;
  gap: 0.8vh;
  padding-bottom: 1.4vh;
}

/* Plain bullet list */
.bullet-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.8vh;
}

.bullet-item {
  position: relative;
  font-family: "assistant-bold";
  font-size: 1vw;
  color: #444444;
  line-height: 1.6;
  padding-right: 1.4vw;
  margin: 0;
}
.bullet-item::before {
  content: '';
  position: absolute;
  right: 0;
  top: 0.7vh;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #3a6b4a;
}

/* Mixed list */
.mixed-list {
  display: flex;
  flex-direction: column;
  gap: 0.8vh;
}

.bullet-item-wrap {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 0.6vw;
  font-family: "assistant-bold";
  font-size: 1vw;
  color: #444444;
  line-height: 1.6;
  direction: rtl;
}

.bullet-dot {
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #3a6b4a;
  margin-top: 0.65vh;
}

/* Sub-header + numbered children */
.sub-block {
  margin-top: 0.4vh;
}

.sub-header {
  font-family: "assistant-extrabold";
  font-size: 1vw;
  color: #1d1d1f;
  text-decoration: underline;
  margin-bottom: 0.6vh;
}

.sub-list {
  margin: 0;
  padding: 0;
  padding-right: 1.8vw;
  list-style: decimal;
  display: flex;
  flex-direction: column;
  gap: 0.6vh;
}

.sub-item {
  font-family: "assistant-bold";
  font-size: 1vw;
  color: #444444;
  line-height: 1.6;
}

/* Legend */
.legend {
  display: flex;
  flex-direction: row;
  justify-content: flex-start;
  gap: 1.5vw;
  margin-bottom: 1vh;
  flex-wrap: wrap;
  direction: rtl;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.4vw;
  direction: rtl;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 1px solid rgba(0,0,0,0.15);
  flex-shrink: 0;
}

.legend-label {
  font-family: "assistant-bold";
  font-size: 0.85vw;
  color: #444444;
}

/* Tables */
.table-wrapper {
  width: 100%;
  overflow-x: auto;
  padding-bottom: 0.5vh;
}

.matzav-table {
  width: 100%;
  border-collapse: collapse;
  direction: rtl;
  font-family: "assistant-bold";
  font-size: 0.95vw;
}

.matzav-table th {
  background: #f0f4f1;
  color: #3a6b4a;
  font-family: "assistant-extrabold";
  font-size: 0.95vw;
  padding: 0.8vh 0.8vw;
  border: 1px solid #d8e8dc;
  text-align: right;
  white-space: nowrap;
}

.matzav-table td {
  padding: 0.7vh 0.8vw;
  border: 1px solid #e8e8e8;
  color: #333333;
  text-align: right;
  line-height: 1.5;
  vertical-align: top;
}

/* LARGE SCREEN */
@media (min-width: 1600px) {
  .page-title      { font-size: 2vw; }
  .section-title   { font-size: 1vw; }
  .toggle-icon     { font-size: 1.2vw; }
  .bullet-item,
  .bullet-item-wrap,
  .sub-item        { font-size: 0.9vw; }
  .sub-header      { font-size: 0.9vw; }
  .matzav-table,
  .matzav-table th,
  .matzav-table td { font-size: 0.8vw; }
  .legend-label    { font-size: 0.75vw; }
}

/* MOBILE */
@media (max-device-width: 600px) {
  #security-text { padding: 10vh 0 6vh; }

  #back { font-size: 3vw; padding: 0.6vh 3vw; right: 2vw; top: 2.5vh; background: #3a6b4a; color: #ffffff; transition: none; }
  #back:hover, #back:active { background: #3a6b4a; color: #ffffff; }

  .page-title  { font-size: 6vw; margin-bottom: 0; }
  .divider     { display: block; width: 12vw; margin-top: 1.5vh; margin-bottom: 3vh; }

  .matzav-panel { width: 90vw; padding: 2vh 5vw; align-self: center; margin-left: auto; margin-right: auto; }

  .section-title     { font-size: 4vw; }
  .toggle-icon       { font-size: 5vw; }
  .bullet-item,
  .bullet-item-wrap,
  .sub-item          { font-size: 3.5vw; }
  .bullet-item       { padding-right: 4vw; }
  .bullet-item::before { top: 1.4vh; }
  .sub-header        { font-size: 3.5vw; }
  .sub-list          { padding-right: 5vw; }
  .bullet-dot        { margin-top: 1.2vh; }

  .table-wrapper     { overflow-x: visible; }
  .matzav-table      { table-layout: fixed; width: 100%; }
  .matzav-table th   { white-space: normal; font-size: 2.6vw; padding: 0.6vh 1.5vw; }
  .matzav-table td   { font-size: 2.6vw; padding: 0.6vh 1.5vw; word-break: break-word; }

  .legend            { gap: 4vw; }
  .legend-label      { font-size: 3vw; }
  .legend-swatch     { width: 12px; height: 12px; }
}
</style>
