<template>
  <div id="nohal-alat">
    <button id="back" @click="back">→ חזרה</button>

    <div class="page-title">נוהל תיאום אל"ת</div>
    <div class="divider"></div>

    <div class="tabs">
      <button class="tab" :class="{ active: activeView === 'matzav' }" @click="activeView = 'matzav'">מצע</button>
      <button class="tab" :class="{ active: activeView === 'charts' }" @click="switchToCharts">שביל הזהב</button>
    </div>

    <div v-if="activeView === 'matzav'" class="matzav-panel">
      <div v-if="matzav.length" class="matzav-sections">
        <div
          v-for="(section, i) in matzav"
          :key="i"
          class="matzav-section"
        >
          <button class="section-toggle" @click="toggleSection(i)">
            <span class="section-title">{{ section.title }}</span>
            <span class="toggle-icon">{{ openSections[i] ? '−' : '+' }}</span>
          </button>
          <div v-if="openSections[i]" class="section-body">
            <template v-if="section.table">
              <div class="table-wrapper">
                <table class="matzav-table">
                  <thead>
                    <tr>
                      <th v-for="(h, hi) in section.table.headers" :key="hi">{{ h }}</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="(row, ri) in section.table.rows" :key="ri">
                      <td v-for="(cell, ci) in row.cells" :key="ci">{{ cell }}</td>
                      <td v-if="row.lastCell" :rowspan="row.lastCell.rowspan" class="merged-cell">{{ row.lastCell.text }}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </template>
            <template v-else>
              <p
                v-for="(line, j) in section.content"
                :key="j"
                class="matzav-line"
              >{{ line }}</p>
            </template>
          </div>
        </div>
      </div>
      <div v-else class="matzav-empty">אין תוכן עדיין</div>
    </div>

    <div v-if="activeView === 'charts'" class="charts-wrapper">
      <div class="chart-section" v-for="(chart, ci) in charts" :key="ci">
        <div class="chart-label">{{ ci + 1 }}</div>
        <div class="chart-flow">
          <template v-for="(step, si) in chart.flowchart">
            <div class="box" :key="'box-' + si">
              <div class="box-main">{{ step }}</div>
              <div class="box-divider"></div>
              <div class="box-extra">{{ chart.extra[si] }}</div>
            </div>
            <div class="arrow" v-if="si < chart.flowchart.length - 1" :key="'arr-' + si">
              <svg width="20" height="12" viewBox="0 0 28 16" fill="none">
                <path d="M28 8H4M4 8L11 2M4 8L11 14" stroke="#3a6b4a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </div>
          </template>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import json from "../../text.json";
export default {
  name: "nohal-alat",
  props: ["tab"],
  data() {
    const matzav = json["nohal-alat"].matzav;
    const openSections = {};
    matzav.forEach((_, i) => { openSections[i] = false; });
    return {
      charts: json["nohal-alat"].charts,
      matzav,
      openSections,
      activeView: "matzav"
    };
  },
  mounted() {
    window.addEventListener("resize", this.equalizeBoxHeights);
  },
  beforeDestroy() {
    window.removeEventListener("resize", this.equalizeBoxHeights);
  },
  methods: {
    back() {
      this.$emit("back");
    },
    toggleSection(i) {
      this.$set(this.openSections, i, !this.openSections[i]);
    },
    switchToCharts() {
      this.activeView = "charts";
      this.$nextTick(this.equalizeBoxHeights);
    },
    equalizeBoxHeights() {
      const boxes = this.$el.querySelectorAll(".box");
      if (!boxes.length) return;
      boxes.forEach(b => (b.style.height = "auto"));
      const maxH = Math.max(...Array.from(boxes).map(b => b.offsetHeight));
      boxes.forEach(b => (b.style.height = maxH + "px"));
    }
  }
};
</script>

