<template>
    <div id="text-page">
      <button id="back" @click="back">→ חזרה</button>
      <fire-areas :title="title" v-if="Number(tabNum) === 0"></fire-areas>
      <refreshing :maintitle="title" v-if="Number(tabNum) === 1"></refreshing>
      <shooting-range :title="title" v-if="Number(tabNum) === 2"></shooting-range>
      <logistics :title="title" v-if="Number(tabNum) === 3"></logistics>
      <structure :title="title" v-if="Number(tabNum) === 4"></structure>
      <routine :title="title" v-if="Number(tabNum) === 5"></routine>
      <nohal-tium-imunim :title="title" v-if="Number(tabNum) === 6"></nohal-tium-imunim>
    </div>
</template>

<script>
import json from "../../text.json";
import FireAreas from "@/components/FireAreas";
import Refreshing from "@/components/Refreshing";
import ShootingRange from "@/components/ShootingRange";
import Logistics from "@/components/Logistics";
import Structure from "@/components/Structure";
import Routine from "@/components/Routine";
import NohalTiumImunim from "@/components/NohalTiumImunim";

export default {
  name: "text-page",
  props: ["tabNum"],
  components: {
    FireAreas,
    Refreshing,
    ShootingRange,
    Logistics,
    Structure,
    Routine,
    NohalTiumImunim
  },
  data() {
    return {
      title: json["topics"][Number(this.tabNum)],
    }
  },
  mounted() {
    this.$el.querySelector('#back').blur();
    this.$el.scrollTop = 0;
    window.scrollTo(0, 0);
  },
  watch: {
    tabNum() {
      this.$nextTick(() => {
        this.$el.scrollTop = 0;
        window.scrollTo(0, 0);
      });
    }
  },
  methods: {
    back(event) {
      event.currentTarget.blur();
      this.$emit("back");
    }
  }
}
</script>

<style scoped>
#text-page {
  position: absolute;
  top: 0;
  right: 0;
  height: 100vh;
  overflow-x: hidden;
  overflow-y: auto;
  width: 100vw;
}
#back {
  position: absolute;
  right: 1.5vw;
  top: 2.5vh;
  z-index: 6;
  font-family: "assistant-bold";
  font-size: 1vw;
  color: #3a6b4a;
  background: transparent;
  border: 1.5px solid #3a6b4a;
  border-radius: 980px;
  padding: 0.7vh 1.5vw;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
#back:hover {
  background: #3a6b4a;
  color: #ffffff;
}

@media (max-device-width: 600px) {
  #back {
    font-size: 3vw;
    padding: 0.6vh 3vw;
    right: 2vw;
    top: 2.5vh;
    background: #3a6b4a;
    color: #ffffff;
    transition: none;
  }
  #back:hover, #back:active {
    background: #3a6b4a;
    color: #ffffff;
  }
}
</style>
