<template>
  <div id="site-password-gate">
    <div class="gate-content">
      <img class="logo" src="@/assets/media/logo.png" alt="לוגו">
      <div class="gate-title">ברוכים הבאים לבא"פ אלייקים</div>
      <div class="gate-subtitle">יש להזין סיסמת כניסה להמשך</div>
      <input
        ref="passwordInput"
        v-model="password"
        type="password"
        class="gate-input"
        placeholder="סיסמה"
        autocomplete="current-password"
        :disabled="loading || isLocked"
        @keyup.enter="submit"
      />
      <transition name="fade-msg">
        <div v-if="isLocked" class="gate-lockout">
          יותר מדי ניסיונות כושלים — נסה שוב בעוד
          <span class="gate-lockout-timer">{{ lockoutDisplay }}</span>
        </div>
        <div v-else-if="error" class="gate-error">{{ error }}</div>
      </transition>
      <button class="gate-btn" :disabled="loading || isLocked" @click="submit">
        {{ loading ? '...' : 'כניסה' }}
      </button>
    </div>
  </div>
</template>

<script>
import { supabase } from '../supabase';

const STORAGE_ATTEMPTS = 'site_pw_attempts';
const STORAGE_LOCKED   = 'site_pw_locked_until';
const MAX_ATTEMPTS     = 5;
const LOCKOUT_MS       = 2 * 60 * 1000;

async function sha256(text) {
  const encoder = new TextEncoder();
  const data = encoder.encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hashBuffer))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}

export default {
  name: 'site-password',
  data() {
    return {
      password: '',
      error: '',
      loading: false,
      attempts: 0,
      lockedUntil: 0,
      timeLeft: 0,
      countdownInterval: null,
    };
  },
  computed: {
    isLocked() {
      return this.timeLeft > 0;
    },
    lockoutDisplay() {
      const m = Math.floor(this.timeLeft / 60);
      const s = String(this.timeLeft % 60).padStart(2, '0');
      return `${m}:${s}`;
    },
  },
  mounted() {
    this.attempts    = parseInt(localStorage.getItem(STORAGE_ATTEMPTS) || '0');
    this.lockedUntil = parseInt(localStorage.getItem(STORAGE_LOCKED)   || '0');

    if (this.lockedUntil > Date.now()) {
      this.startCountdown();
    } else if (this.lockedUntil > 0) {
      this.clearLockout();
    }

    this.$nextTick(() => {
      if (this.$refs.passwordInput && !this.isLocked) this.$refs.passwordInput.focus();
    });
  },
  beforeDestroy() {
    if (this.countdownInterval) clearInterval(this.countdownInterval);
  },
  methods: {
    startCountdown() {
      this.timeLeft = Math.ceil((this.lockedUntil - Date.now()) / 1000);
      this.countdownInterval = setInterval(() => {
        this.timeLeft = Math.ceil((this.lockedUntil - Date.now()) / 1000);
        if (this.timeLeft <= 0) {
          clearInterval(this.countdownInterval);
          this.countdownInterval = null;
          this.clearLockout();
          this.$nextTick(() => {
            if (this.$refs.passwordInput) this.$refs.passwordInput.focus();
          });
        }
      }, 1000);
    },
    clearLockout() {
      this.timeLeft    = 0;
      this.lockedUntil = 0;
      this.attempts    = 0;
      localStorage.removeItem(STORAGE_ATTEMPTS);
      localStorage.removeItem(STORAGE_LOCKED);
    },
    recordFailure() {
      this.attempts++;
      localStorage.setItem(STORAGE_ATTEMPTS, this.attempts);
      if (this.attempts >= MAX_ATTEMPTS) {
        this.lockedUntil = Date.now() + LOCKOUT_MS;
        localStorage.setItem(STORAGE_LOCKED, this.lockedUntil);
        this.error = '';
        this.startCountdown();
      } else {
        this.error = `סיסמה שגויה — נותרו ${MAX_ATTEMPTS - this.attempts} ניסיונות`;
      }
    },
    async submit() {
      if (this.isLocked || !this.password) {
        if (!this.password) this.error = 'יש להזין סיסמה';
        return;
      }
      this.loading = true;
      this.error = '';
      try {
        const { data, error } = await supabase
          .from('site_settings')
          .select('value')
          .eq('key', 'site_password_hash')
          .maybeSingle();

        if (error) throw error;

        if (!data) {
          this.verify();
          return;
        }

        const hash = await sha256(this.password);
        if (hash === data.value) {
          this.verify();
        } else {
          this.password = '';
          this.recordFailure();
          this.$nextTick(() => {
            if (this.$refs.passwordInput && !this.isLocked) this.$refs.passwordInput.focus();
          });
        }
      } catch {
        this.error = 'שגיאה בבדיקת הסיסמה, נסה שוב';
      } finally {
        this.loading = false;
      }
    },
    verify() {
      localStorage.removeItem(STORAGE_ATTEMPTS);
      localStorage.removeItem(STORAGE_LOCKED);
      sessionStorage.setItem('site_verified', 'true');
      this.$emit('verified');
    },
  },
};
</script>

