<template>
  <div id="home-page">
    <div class="content">
      <img class="logo" src="@/assets/media/logo.png" alt="לוגו">
      <div class="main-title">בחר נושא</div>
      <div class="divider"></div>
      <div class="grid">
        <button
          v-for="(topic, index) in topics"
