          <span class="topic-text">{{ topic }}</span>
        </button>
      </div>
    </div>

    <!-- Admin lock button -->
    <button class="admin-toggle-btn" @click="onAdminToggle" :title="session ? 'ניהול' : 'כניסת מנהל'">
      {{ session ? '🔓' : '🔒' }}
    </button>

    <!-- Admin panel modal -->
    <transition name="modal-fade">
      <div v-if="showAdminPanel" class="modal-overlay" @click.self="showAdminPanel = false">
        <div class="password-modal admin-panel-modal">
          <div class="modal-title">ניהול</div>
          <button class="admin-action-btn" @click="openChangeSitePassword">סיסמת האתר</button>
          <button class="admin-action-btn" @click="openChangePassword">שינוי סיסמה</button>
          <button class="admin-action-btn admin-action-btn-logout" @click="logout">יציאה</button>
        </div>
      </div>
    </transition>

    <!-- Login modal -->
    <transition name="modal-fade">
      <div v-if="showLoginModal" class="modal-overlay" @click.self="closeLoginModal">
        <div class="password-modal">
          <template v-if="!forgotPasswordMode">
            <div class="modal-title">כניסת מנהל</div>
            <input
              ref="loginEmailInput"
              v-model="loginEmail"
              type="email"
              class="modal-pw-input"
              placeholder="אימייל"
              autocomplete="email"
              @keyup.enter="$refs.loginPasswordInput.focus()"
            />
            <input
              ref="loginPasswordInput"
              v-model="loginPassword"
              type="password"
              class="modal-pw-input"
              placeholder="סיסמה"
              autocomplete="current-password"
              @keyup.enter="submitLogin"
            />
            <div v-if="loginError" class="modal-error">{{ loginError }}</div>
            <button class="forgot-password-link" @click="openForgotPassword">שכחתי סיסמה</button>
            <div class="modal-btns">
              <button class="modal-btn-cancel" @click="closeLoginModal">ביטול</button>
              <button class="modal-btn-ok" @click="submitLogin" :disabled="loginLoading">
                {{ loginLoading ? '...' : 'כניסה' }}
              </button>
            </div>
          </template>
          <template v-else>
            <div class="modal-title">איפוס סיסמה</div>
            <template v-if="!forgotPasswordSent">
              <div class="modal-subtitle">נשלח אליך מייל עם קישור לאיפוס הסיסמה</div>
              <input
                ref="forgotEmailInput"
                v-model="forgotPasswordEmail"
                type="email"
                class="modal-pw-input"
                placeholder="אימייל"
                autocomplete="email"
                @keyup.enter="submitForgotPassword"
              />
              <div v-if="forgotPasswordError" class="modal-error">{{ forgotPasswordError }}</div>
              <div class="modal-btns">
                <button class="modal-btn-cancel" @click="forgotPasswordMode = false">חזור</button>
                <button class="modal-btn-ok" @click="submitForgotPassword" :disabled="forgotPasswordLoading">
                  {{ forgotPasswordLoading ? '...' : 'שלח' }}
                </button>
              </div>
            </template>
            <template v-else>
              <div class="modal-success">המייל נשלח! בדוק את תיבת הדואר שלך ולחץ על הקישור לאיפוס הסיסמה.</div>
              <div class="modal-btns">
                <button class="modal-btn-ok" @click="closeLoginModal">סגור</button>
              </div>
            </template>
          </template>
        </div>
      </div>
    </transition>

    <!-- Site password modal -->
    <transition name="modal-fade">
      <div v-if="showChangeSitePasswordModal" class="modal-overlay" @click.self="closeChangeSitePassword">
        <div class="password-modal">
          <div class="modal-title">סיסמת כניסה לאתר</div>
          <div class="modal-desc">הסיסמה תידרש מכל משתמש בכניסה לאתר</div>
          <input
            v-model="sitePasswordNew"
            type="password"
            class="modal-pw-input"
            placeholder="סיסמה חדשה"
            autocomplete="new-password"
          />
          <input
            v-model="sitePasswordConfirm"
            type="password"
            class="modal-pw-input"
            placeholder="אימות סיסמה"
            autocomplete="new-password"
            @keyup.enter="submitChangeSitePassword"
          />
          <div v-if="sitePasswordError" class="modal-error">{{ sitePasswordError }}</div>
          <div v-if="sitePasswordSuccess" class="modal-success">הסיסמה עודכנה בהצלחה</div>
          <div class="modal-btns">
            <button class="modal-btn-cancel" @click="closeChangeSitePassword">ביטול</button>
            <button class="modal-btn-ok" @click="submitChangeSitePassword" :disabled="sitePasswordLoading">
              {{ sitePasswordLoading ? '...' : 'שמור' }}
            </button>
          </div>
        </div>
      </div>
    </transition>

