</template>

<script>
import json from "../../text.json";
import { supabase } from '../supabase';

export default {
  name: "home-page",
  emits: ["chosenNum"],
  data() {
    return {
      topics: json.topics,
      shiningIndex: null,
      // Auth
      session: null,
      showAdminPanel: false,
      // Login modal
      showLoginModal: false,
      loginEmail: "",
      loginPassword: "",
      loginError: "",
      loginLoading: false,
      // Forgot password
      forgotPasswordMode: false,
      forgotPasswordEmail: "",
      forgotPasswordError: "",
      forgotPasswordSent: false,
      forgotPasswordLoading: false,
      // Site password modal
      showChangeSitePasswordModal: false,
      sitePasswordNew: "",
      sitePasswordConfirm: "",
      sitePasswordError: "",
      sitePasswordSuccess: false,
      sitePasswordLoading: false,
      // Change password modal
      showChangePasswordModal: false,
      changeNewPassword: "",
      changeConfirmPassword: "",
      changePasswordError: "",
      changePasswordLoading: false,
    };
  },
  async mounted() {
    if (document.activeElement) document.activeElement.blur();

    const { data: { session } } = await supabase.auth.getSession();
    this.session = session;

    supabase.auth.onAuthStateChange((event, session) => {
      this.session = session;
      if (event === 'SIGNED_OUT') this.session = null;
    });
  },
  methods: {
    triggerShine(index, event) {
      if (event && event.currentTarget) event.currentTarget.blur();
      this.shiningIndex = null;
      this.$nextTick(() => { this.shiningIndex = index; });
      setTimeout(() => {
        this.$emit("chosenNum", index);
        this.shiningIndex = null;
      }, 420);
    },
    onAdminToggle() {
      if (this.session) {
        this.showAdminPanel = true;
      } else {
        this.showLoginModal = true;
        this.loginEmail = "";
        this.loginPassword = "";
        this.loginError = "";
        this.$nextTick(() => {
          if (this.$refs.loginEmailInput) this.$refs.loginEmailInput.focus();
        });
      }
    },
    closeLoginModal() {
      this.showLoginModal = false;
      this.loginEmail = "";
      this.loginPassword = "";
      this.loginError = "";
      this.forgotPasswordMode = false;
      this.forgotPasswordEmail = "";
      this.forgotPasswordError = "";
      this.forgotPasswordSent = false;
    },
    openForgotPassword() {
      this.forgotPasswordMode = true;
      this.forgotPasswordEmail = this.loginEmail;
      this.forgotPasswordError = "";
      this.forgotPasswordSent = false;
      this.$nextTick(() => {
        if (this.$refs.forgotEmailInput) this.$refs.forgotEmailInput.focus();
      });
    },
    async submitForgotPassword() {
      this.forgotPasswordError = "";
      if (!this.forgotPasswordEmail.trim()) {
        this.forgotPasswordError = "יש להזין כתובת אימייל";
        return;
      }
      this.forgotPasswordLoading = true;
      const { error } = await supabase.auth.resetPasswordForEmail(
        this.forgotPasswordEmail,
        { redirectTo: window.location.href }
      );
      this.forgotPasswordLoading = false;
      if (error) {
        this.forgotPasswordError = "שגיאה בשליחת המייל, נסה שוב";
      } else {
        this.forgotPasswordSent = true;
      }
    },
    async submitLogin() {
      this.loginError = "";
      this.loginLoading = true;
      const { error } = await supabase.auth.signInWithPassword({
        email: this.loginEmail,
        password: this.loginPassword
      });
      this.loginLoading = false;
      if (error) {
        this.loginError = "אימייל או סיסמה שגויים";
      } else {
        this.closeLoginModal();
      }
    },
    async logout() {
      await supabase.auth.signOut();
      this.showAdminPanel = false;
    },
    openChangeSitePassword() {
      this.showAdminPanel = false;
      this.sitePasswordNew = "";
      this.sitePasswordConfirm = "";
      this.sitePasswordError = "";
      this.sitePasswordSuccess = false;
      this.showChangeSitePasswordModal = true;
    },
    closeChangeSitePassword() {
      this.showChangeSitePasswordModal = false;
      this.sitePasswordNew = "";
      this.sitePasswordConfirm = "";
      this.sitePasswordError = "";
      this.sitePasswordSuccess = false;
    },
    async submitChangeSitePassword() {
      this.sitePasswordError = "";
      this.sitePasswordSuccess = false;
      if (!this.sitePasswordNew) {
        this.sitePasswordError = "יש להזין סיסמה";
        return;
      }
      if (this.sitePasswordNew !== this.sitePasswordConfirm) {
        this.sitePasswordError = "הסיסמאות אינן תואמות";
        return;
      }
      this.sitePasswordLoading = true;
      try {
        const encoder = new TextEncoder();
        const data = encoder.encode(this.sitePasswordNew);
        const hashBuffer = await crypto.subtle.digest('SHA-256', data);
        const hash = Array.from(new Uint8Array(hashBuffer))
          .map(b => b.toString(16).padStart(2, '0'))
          .join('');
        const { error } = await supabase
          .from('site_settings')
          .upsert({ key: 'site_password_hash', value: hash, updated_at: new Date().toISOString() });
        if (error) throw error;
        this.sitePasswordSuccess = true;
        this.sitePasswordNew = "";
        this.sitePasswordConfirm = "";
        sessionStorage.removeItem('site_verified');
      } catch {
        this.sitePasswordError = "שגיאה בשמירת הסיסמה, נסה שוב";
      } finally {
        this.sitePasswordLoading = false;
      }
    },
    openChangePassword() {
      this.showAdminPanel = false;
      this.changeNewPassword = "";
      this.changeConfirmPassword = "";
      this.changePasswordError = "";
      this.showChangePasswordModal = true;
    },
    closeChangePassword() {
      this.showChangePasswordModal = false;
      this.changeNewPassword = "";
      this.changeConfirmPassword = "";
      this.changePasswordError = "";
    },
    async submitChangePassword() {
      this.changePasswordError = "";
      if (this.changeNewPassword.length < 6) {
        this.changePasswordError = "הסיסמה חייבת להכיל לפחות 6 תווים";
        return;
      }
      if (this.changeNewPassword !== this.changeConfirmPassword) {
        this.changePasswordError = "הסיסמאות אינן תואמות";
        return;
      }
      this.changePasswordLoading = true;
      const { error } = await supabase.auth.updateUser({ password: this.changeNewPassword });
      this.changePasswordLoading = false;
      if (error) {
        this.changePasswordError = "שגיאה בשינוי הסיסמה";
      } else {
        this.closeChangePassword();
      }
    },
  }
};
</script>

